 .section .text.trap
.global {{trapName}}
{{trapName}}:
    addi sp, sp, -{{frameSize}}
    sw ra, {{raOffset}}(sp)
    csrr a0, mcause
    csrr a1, mepc
    {{body}}
    lw ra, {{raOffset}}(sp)
    addi sp, sp, {{frameSize}}
    mret

 .syntax unified
.thumb

.equ RCC_AHBENR, {{rccAhbEnr}}
.equ GPIOx_MODER, {{gpioModer}}
.equ GPIOx_BSRR,  {{gpioBsrr}}

.global {{functionName}}
{{functionName}}:
    ldr r0, =RCC_AHBENR
    ldr r1, [r0]
    orr r1, r1, #{{clockEnableMask}}
    str r1, [r0]

    ldr r0, =GPIOx_MODER
    ldr r1, [r0]
    orr r1, r1, #{{moderMask}}
    str r1, [r0]

    ldr r0, =GPIOx_BSRR
    movs r1, #{{pinSetMask}}
    str r1, [r0]
    bx lr
